INSERT INTO feature VALUES('bidirectional-checking','checking','Bidirectional checking',NULL,'implemented','notable',NULL,'Four directed faces check or synthesise values and computations, formation itself a judgement; a return synthesises its value''s pure returner. A lambda checked against a returner of a box of a function stands as that box returned, so a body that returns a function value may end in a bare lambda.','core-checker','corpus/fragment/non-synthesisable-head.gandr corpus/model/control/held-read.gandr corpus/model/control/statement-block.gandr corpus/model/control/tail-lambda.gandr','corpus/model/control/held-read.gandr',NULL);
